import {CreateSpaceDialog} from '@github-ui/copilot-spaces/components/CreateSpaceDialog'
import {sendEvent} from '@github-ui/hydro-analytics'
import {Button} from '@primer/react'
import {useState} from 'react'

type CreateSpaceButtonProps = {
  primary?: boolean
}

// Creates a default Space owned by the current user
export function CreateSpaceButton({primary = false}: CreateSpaceButtonProps) {
  const [showCreateSpaceDialog, setShowCreateSpaceDialog] = useState(false)

  const closeCreateSpaceDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CREATE_DIALOG_CLOSE', mode: 'immersive'})
    setShowCreateSpaceDialog(false)
  }

  const onCreateSpace = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CREATE_DIALOG_OPEN', mode: 'immersive'})
    setShowCreateSpaceDialog(true)
  }

  const onSubmit = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACES_SPACE_CREATED', mode: 'immersive'})
  }

  return (
    <>
      {showCreateSpaceDialog ? <CreateSpaceDialog closeDialog={closeCreateSpaceDialog} onSubmit={onSubmit} /> : null}
      <Button variant={primary ? 'primary' : 'default'} onClick={onCreateSpace}>
        Create space
      </Button>
    </>
  )
}

try{ CreateSpaceButton.displayName ||= 'CreateSpaceButton' } catch {}