import {useNavigateToNewThread} from '@github-ui/copilot-chat/hooks/use-navigate-to-new-thread'
import {ComposeIcon} from '@github-ui/pacer/CustomIcon'
import {IconButton} from '@primer/react'

import styles from './NewChatButton.module.css'

export function NewChatButton() {
  const navigateToNewThread = useNavigateToNewThread()

  const handleClick = async () => {
    await navigateToNewThread({clearTopic: true, includeThreads: false})
  }

  return (
    <div className={styles.newChatButtonContainer}>
      <IconButton icon={ComposeIcon} onClick={handleClick} aria-label="New chat" />
    </div>
  )
}

try{ NewChatButton.displayName ||= 'NewChatButton' } catch {}