import type {CopilotSpace, IndexCopilotSpace} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'

export function getVisibilityText(copilotSpace: CopilotSpace | IndexCopilotSpace): string {
  const isShared = copilotFeatureFlags.copilotSpacesReadAccessToUserOwnedSpaces ? copilotSpace.collaborative : false

  if (!copilotSpace.shareable) return 'Private'

  if (isShared) return 'Shared'

  switch (copilotSpace.baseRole) {
    case 'custom_copilot_reader':
    case 'custom_copilot_writer':
    case 'custom_copilot_admin':
      return 'Shared'
  }

  switch (copilotSpace.visibility) {
    case 'org_public':
      return 'Shared'
  }

  return 'Private'
}
