function SpacesListItem({copilotSpace, onDelete, onClick}: SpacesListItemProps) {
  const OwnerIcon = copilotSpace.ownerIsOrg ? OrganizationIcon : PersonIcon
  const visibilityText = getVisibilityText(copilotSpace)
  const VisibilityIcon = visibilityText === 'Shared' ? PeopleIcon : LockIcon
  const showSpacesMenu = copilotSpace.adminable || copilotSpace.editable

  return (
    <ListBlock.Item href={getCopilotSpacePath(copilotSpace)} onClick={onClick}>
      <ListBlock.Item.Title>{copilotSpace.name}</ListBlock.Item.Title>
      <ListBlock.Item.Description>
        <div className={styles.description}>{copilotSpace.description}</div>
      </ListBlock.Item.Description>
      <ListBlock.Item.Metadata>
        <div className={styles.metadata}>
          <span className={styles.metadataItem}>
            <OwnerIcon size={16} />
            {copilotSpace.owner}
          </span>
          <span className={styles.metadataItem}>
            <VisibilityIcon size={16} />
            {visibilityText}
          </span>
        </div>
      </ListBlock.Item.Metadata>
      {(showSpacesMenu || copilotFeatureFlags.copilotSpacesReportAbuse) && (
        <ListBlock.Item.Actions>
          <CopilotSpacesMenu copilot={copilotSpace} onDelete={onDelete} />
        </ListBlock.Item.Actions>
      )}
    </ListBlock.Item>
  )
}

