const shouldShowInSharedTab = (copilotSpace: CopilotSpace | IndexCopilotSpace) =>
  copilotSpace.shared && copilotSpace.collaborative

function SpacesList({
  spaces,
  categorizedSpaces,
  starredSpaces,
  isLoading,
  categorizedLoading,
  spacesCounts,
  isCountsLoading,
  onDelete,
  onSpaceClick,
  searchQuery,
  currentUserLogin,
}: SpacesListProps) {
  const spacesSelectedTab = copilotLocalStorage.getSpacesSelectedTab()

  const [activeTab, setActiveTab] = useState<CopilotSpaceTab>(spacesSelectedTab)

  const handleChangeTab = useCallback((tab: CopilotSpaceTab) => {
    setActiveTab(tab)
    copilotLocalStorage.setSpacesSelectedTab(tab)
  }, [])

  const hasStarred = starredSpaces && starredSpaces.length > 0
  const sharedByMeTabEnabled = copilotFeatureFlags.copilotSpacesReadAccessToUserOwnedSpaces

  useEffect(() => {
    if (hasStarred) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      handleChangeTab('starred')
    }
  }, [hasStarred, handleChangeTab])

  // Determine loading state for the active tab
  const isActiveTabLoading = useMemo(() => {
    if (!categorizedLoading) return isLoading

    switch (activeTab) {
      case 'starred':
        return categorizedLoading.starred
      case 'personal':
        return categorizedLoading.userOwned
      case 'org':
        return categorizedLoading.orgOwned
      case 'shared':
        return categorizedLoading.sharedWithUser
      default:
        return isLoading
    }
  }, [categorizedLoading, activeTab, isLoading])

  // Get the spaces for the active tab directly from categorized spaces if available
  const activeTabSpaces = useMemo(() => {
    // If categorized spaces are available, use them directly based on active tab
    if (categorizedSpaces) {
      switch (activeTab) {
        case 'starred':
          return categorizedSpaces.starred
        case 'personal':
          return categorizedSpaces.userOwned
        case 'org':
          return categorizedSpaces.orgOwned
        case 'shared':
          return categorizedSpaces.sharedWithUser
        default:
          return undefined
      }
    }

    // Fall back to filtering the combined spaces array (legacy behavior)
    if (!spaces) return undefined

    return spaces.filter(space => {
      const matchesTab =
        (activeTab === 'starred' && space.starred) ||
        (activeTab === 'personal' && !space.ownerIsOrg && !space.shared) ||
        (activeTab === 'org' && space.ownerIsOrg) ||
        (sharedByMeTabEnabled ? activeTab === 'shared' && shouldShowInSharedTab(space) : false)
      return matchesTab
    })
  }, [categorizedSpaces, spaces, activeTab, sharedByMeTabEnabled])

  // Apply search filtering to the active tab spaces
  const filteredSpaces = useMemo(() => {
    if (!activeTabSpaces) return []

    if (!searchQuery.trim()) return activeTabSpaces

    return activeTabSpaces.filter(space => matchesCommonSearch(space, searchQuery))
  }, [activeTabSpaces, searchQuery])

  // Calculate tab counts - use spacesCounts from API if available, otherwise fall back to calculating from arrays
  const {personalSpacesCount, orgSpacesCount, starredSpacesCount, sharedSpacesCount} = useMemo(() => {
    // If we have counts from the API and no search query, use them directly
    if (spacesCounts && !searchQuery.trim()) {
      return {
        personalSpacesCount: spacesCounts.user_owned_spaces,
        orgSpacesCount: spacesCounts.org_owned_spaces,
        starredSpacesCount: spacesCounts.starred_spaces,
        sharedSpacesCount: sharedByMeTabEnabled ? spacesCounts.shared_with_me_spaces : 0,
      }
    }

    // If there's a search query, we need to filter and count manually
    if (categorizedSpaces) {
      // Use categorized spaces directly for counts
      const applySearchFilter = (arr: IndexCopilotSpace[] | undefined) => {
        if (!arr) return 0
        if (!searchQuery.trim()) return arr.length
        return arr.filter(space => matchesCommonSearch(space, searchQuery)).length
      }

      return {
        personalSpacesCount: applySearchFilter(categorizedSpaces.userOwned),
        orgSpacesCount: applySearchFilter(categorizedSpaces.orgOwned),
        starredSpacesCount: applySearchFilter(categorizedSpaces.starred),
        sharedSpacesCount: sharedByMeTabEnabled ? applySearchFilter(categorizedSpaces.sharedWithUser) : 0,
      }
    }

    // Fall back to legacy behavior
    if (!spaces) return {personalSpacesCount: 0, orgSpacesCount: 0, starredSpacesCount: 0, sharedSpacesCount: 0}

    // Apply search filter first
    const filtered = searchQuery.trim() ? spaces.filter(space => matchesCommonSearch(space, searchQuery)) : spaces

    return {
      personalSpacesCount: filtered.filter(space => !space.ownerIsOrg && !space.shared).length,
      orgSpacesCount: filtered.filter(space => space.ownerIsOrg).length,
      starredSpacesCount: filtered.filter(space => space.starred).length,
      sharedSpacesCount: sharedByMeTabEnabled ? filtered.filter(shouldShowInSharedTab).length : 0,
    }
  }, [spacesCounts, categorizedSpaces, spaces, searchQuery, sharedByMeTabEnabled])

  // Helper to count total unfiltered spaces
  const getTotalSpacesCount = useCallback((): number => {
    if (spacesCounts) {
      return (
        spacesCounts.starred_spaces +
        spacesCounts.user_owned_spaces +
        spacesCounts.org_owned_spaces +
        spacesCounts.shared_with_me_spaces
      )
    }
    if (categorizedSpaces) {
      return (
        (categorizedSpaces.starred?.length ?? 0) +
        (categorizedSpaces.userOwned?.length ?? 0) +
        (categorizedSpaces.orgOwned?.length ?? 0) +
        (categorizedSpaces.sharedWithUser?.length ?? 0)
      )
    }
    return spaces?.length ?? 0
  }, [spacesCounts, categorizedSpaces, spaces])

  // Helper to get all spaces for creator check
  const getAllSpaces = useCallback((): IndexCopilotSpace[] => {
    if (categorizedSpaces) {
      return [
        ...(categorizedSpaces.starred ?? []),
        ...(categorizedSpaces.userOwned ?? []),
        ...(categorizedSpaces.orgOwned ?? []),
        ...(categorizedSpaces.sharedWithUser ?? []),
      ]
    }
    return spaces ?? []
  }, [categorizedSpaces, spaces])

  const hasAnySpaces = getTotalSpacesCount() > 0

  const hasNotCreatedASpace = useMemo(() => {
    const allSpaces = getAllSpaces()
    return allSpaces.length > 0 && !allSpaces.some(space => space.creator === currentUserLogin) && !isActiveTabLoading
  }, [getAllSpaces, currentUserLogin, isActiveTabLoading])

  const hasNoMatchingSpaces = hasAnySpaces && filteredSpaces?.length === 0 && !isActiveTabLoading

  // Announce search results to screen readers
  useEffect(() => {
    // Don't announce while loading or if there's no search query
    if (isActiveTabLoading || !searchQuery.trim()) return

    const count = filteredSpaces.length
    const message = count === 0 ? 'No spaces found.' : `${count} ${count === 1 ? 'space' : 'spaces'} found.`
    announce(message)
  }, [filteredSpaces.length, searchQuery, isActiveTabLoading])

  return (
    <ListBlock>
      <ListBlock.Header>
        {/* This really needs a loading state*/}
        <div role="tablist" aria-label="Filter spaces" className={styles.filterButtons}>
          <button
            onClick={() => handleChangeTab('starred')}
            role="tab"
            aria-selected={activeTab === 'starred'}
            aria-controls="spaces-list"
            id="starred-tab"
            className={styles.button}
          >
            Starred <span className={styles.counter}>{isCountsLoading && !searchQuery ? '' : starredSpacesCount}</span>
          </button>
          <button
            onClick={() => handleChangeTab('personal')}
            role="tab"
            aria-selected={activeTab === 'personal'}
            aria-controls="spaces-list"
            id="personal-tab"
            className={styles.button}
          >
            Yours <span className={styles.counter}>{isCountsLoading && !searchQuery ? '' : personalSpacesCount}</span>
          </button>
          {sharedByMeTabEnabled && (
            <button
              onClick={() => handleChangeTab('shared')}
              role="tab"
              aria-selected={activeTab === 'shared'}
              aria-controls="spaces-list"
              id="shared-with-me-tab"
              className={clsx(styles.button, styles.sharedSpacesTab)}
            >
              Shared with me{' '}
              <span className={styles.counter}>{isCountsLoading && !searchQuery ? '' : sharedSpacesCount}</span>
            </button>
          )}
          <button
            onClick={() => handleChangeTab('org')}
            role="tab"
            aria-selected={activeTab === 'org'}
            aria-controls="spaces-list"
            id="org-tab"
            className={styles.button}
          >
            Organizations{' '}
            <span className={styles.counter}>{isCountsLoading && !searchQuery ? '' : orgSpacesCount}</span>
          </button>
        </div>
      </ListBlock.Header>
      <ListBlock.List loading={isActiveTabLoading} id="spaces-list" aria-labelledby={activeTab}>
        {hasNotCreatedASpace && filteredSpaces?.length === 0 ? (
          <FirstSpaceEmptyState />
        ) : hasNoMatchingSpaces ? (
          <ListBlock.EmptyState>
            <p>
              {activeTab === 'starred' && 'Spaces you star will appear here.'}
              {activeTab === 'personal' && 'Spaces you create will appear here.'}
              {activeTab === 'org' && 'Spaces belonging to your organizations will appear here.'}
              {activeTab === 'shared' && 'Shared spaces will appear here.'}
            </p>
            <CreateSpaceButton />
            <DocsLink />
          </ListBlock.EmptyState>
        ) : (
          filteredSpaces?.map(copilotSpace => (
            <SpacesListItem
              key={copilotSpace.owner ? `${copilotSpace.owner}/${copilotSpace.id}` : copilotSpace.id}
              copilotSpace={copilotSpace}
              onDelete={() => onDelete(copilotSpace)}
              onClick={onSpaceClick}
            />
          ))
        )}
      </ListBlock.List>
    </ListBlock>
  )
}

export function SpacesView({copilotSpaces}: SpacesViewProps) {
  const state = useChatState()
  const {ssoOrganizations} = state
  const splitIndexCallsEnabled = isFeatureEnabled('copilot_spaces_split_index_calls')

  const {categorizedSpaces, categorizedLoading} = useFetchCategorizedSpaces(splitIndexCallsEnabled)

  const allProtectedOrgs = ssoOrganizations.map(org => org.login)

  const [deletionError, setDeletionError] = useState<Error | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const spacesMcpBannerDismissalCount = copilotLocalStorage.getSpacesMcpBannerDismissalCount()
  const shouldShowMcpBanner = spacesMcpBannerDismissalCount < 2
  const [isBannerShown, setIsBannerShown] = useState(shouldShowMcpBanner)

  // Fetch spaces counts from the API when feature flag is enabled
  const {data: spacesCounts, isLoading: isCountsLoading} = useFetchSpacesCount(splitIndexCallsEnabled)

  const isLoading = copilotSpaces === undefined

  // Get starred spaces from categorized or legacy
  const starredSpaces = splitIndexCallsEnabled
    ? categorizedSpaces?.starred
    : copilotSpaces?.filter(space => space.starred)

  const {mutateAsync: deleteCustomCopilot} = useDeleteCopilotSpace()

  const handleCopilotSpaceDelete = async (item: CopilotSpaceId) => {
    try {
      await deleteCustomCopilot(item)
      setDeletionError(null)
    } catch (err) {
      setDeletionError(err instanceof Error ? err : new Error(String(err)))
    }
  }

  const handleOnClickCopilotSpace = () => {
    sendEvent('dotcom_chat.activate', {
      target: 'SPACES_VIEW_SPACE_SELECTED',
      mode: 'immersive',
    })
  }

  const handleSpacesMcpBannerDismissal = () => {
    const currentCount = copilotLocalStorage.getSpacesMcpBannerDismissalCount()
    copilotLocalStorage.setSpacesMcpBannerDismissalCount(currentCount + 1)
    setIsBannerShown(false)
  }

  return (
    <ErrorBoundary fallback={<ErrorFallback regionName="Spaces" />}>
      {deletionError && (
        <Flash variant="danger">
          <AlertIcon />
          There was a problem deleting your space.
        </Flash>
      )}
      <ContentView.Container width="small">
        {isBannerShown && (
          <ContentView.Banner>
            <Banner
              title="Try Spaces in VSCode"
              hideTitle
              icon={<McpIcon />}
              description="Spaces are now available through the GitHub MCP in VSCode."
              variant="upsell"
              primaryAction={
                <Banner.PrimaryAction as="a" href={MCP_LINK} target="_blank" rel="noopener noreferrer">
                  Install
                </Banner.PrimaryAction>
              }
              onDismiss={() => {
                handleSpacesMcpBannerDismissal()
              }}
            />
          </ContentView.Banner>
        )}
        <ContentView.Header>
          <ContentView.Title>{title}</ContentView.Title>
          <ContentView.Description>{description}</ContentView.Description>
          <ContentView.Actions>
            <CreateSpaceButton primary />
          </ContentView.Actions>
        </ContentView.Header>

        {ssoOrganizations.length > 0 && !isFeatureEnabled('global_sso_banner') && (
          <div className={styles.banner}>
            <SingleSignOnBanner
              protectedOrgs={allProtectedOrgs}
              redirectURI={() =>
                `/search/refresh_blackbird_caches?return_to=${encodeURIComponent(window.location.href)}`
              }
            />
          </div>
        )}

        <SearchInput onSearch={setSearchQuery} aria-label="Search spaces" />

        <ContentView.Section>
          <SpacesList
            spaces={copilotSpaces}
            categorizedSpaces={splitIndexCallsEnabled ? categorizedSpaces : undefined}
            starredSpaces={starredSpaces}
            isLoading={isLoading}
            categorizedLoading={splitIndexCallsEnabled ? categorizedLoading : undefined}
            spacesCounts={spacesCounts}
            isCountsLoading={isCountsLoading}
            onDelete={handleCopilotSpaceDelete}
            onSpaceClick={handleOnClickCopilotSpace}
            searchQuery={searchQuery}
            currentUserLogin={state.currentUserLogin}
          />
        </ContentView.Section>
      </ContentView.Container>
    </ErrorBoundary>
  )
}

