import type {CopilotSpace} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {SpaceDialogFooter} from '@github-ui/copilot-spaces/components/SpaceDialogFooter'
import {useUpsertCopilotSpace} from '@github-ui/copilot-spaces/hooks/use-upsert-copilot-space'
import {Banner, FormControl, Textarea} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useState} from 'react'

interface DescriptionDialogProps {
  copilotSpace: CopilotSpace
  onClose: () => void
  onSaved?: (updatedSpace: CopilotSpace) => void
  returnFocusRef: React.RefObject<HTMLButtonElement | null>
  maxDescriptionLength: number
}

export function DescriptionDialog({
  copilotSpace,
  onClose,
  onSaved,
  returnFocusRef,
  maxDescriptionLength,
}: DescriptionDialogProps) {
  const {upsertCopilotSpace, isPending} = useUpsertCopilotSpace(copilotSpace)

  const [description, setDescription] = useState(copilotSpace.description ?? '')
  const [error, setError] = useState<string | null>(null)

  async function saveDescription() {
    try {
      /* upsertCopilotSpace returns the updated space */
      const updatedSpace = await upsertCopilotSpace({description})
      onSaved?.(updatedSpace)
      onClose()
    } catch (err: unknown) {
      if (err instanceof Error) {
        setError(err.message)
      } else {
        setError('Failed to save description')
      }
    }
  }

  function handleCancel() {
    setDescription(copilotSpace.description ?? '')
    onClose()
  }

  return (
    <Dialog
      title="Description"
      onClose={handleCancel}
      returnFocusRef={returnFocusRef}
      position={{narrow: 'fullscreen'}}
      renderBody={() => (
        <div className="p-3">
          {error && <Banner variant="critical" title={error} className="mb-2" />}
          <FormControl>
            <FormControl.Label visuallyHidden>Description</FormControl.Label>
            <Textarea
              block
              value={description}
              onChange={e => setDescription(e.target.value)}
              placeholder="Describe what this space is for"
              resize="vertical"
              rows={5}
            />
            <CharacterCount text={description} promptCharLimit={maxDescriptionLength} />
          </FormControl>
        </div>
      )}
      renderFooter={() => (
        <SpaceDialogFooter
          onCancel={handleCancel}
          onSave={saveDescription}
          isLoading={isPending}
          loadingAnnouncement="Saving description"
          saveButtonText="Save"
        />
      )}
    />
  )
}

function CharacterCount({text, promptCharLimit}: {text: string; promptCharLimit: number}) {
  const tooLong = text.length > promptCharLimit
  const currentCount = (
    <>
      {text.length.toLocaleString()} / {promptCharLimit.toLocaleString()} characters
    </>
  )
  return tooLong ? (
    <FormControl.Validation variant="error">{currentCount}</FormControl.Validation>
  ) : (
    // eslint-disable-next-line primer-react/direct-slot-children
    <FormControl.Caption>{currentCount}</FormControl.Caption>
  )
}

try{ DescriptionDialog.displayName ||= 'DescriptionDialog' } catch {}
try{ CharacterCount.displayName ||= 'CharacterCount' } catch {}